add_action( 'template_redirect', 'perfectpixel_default_account_tab_redirect' );
add_filter( 'woocommerce_account_menu_items', 'perfectpixel_default_account_tab_menu', 40 );

function perfectpixel_default_account_tab_redirect() {
	$tab = sanitize_key( '{{default_account_tab}}' );
	if ( ! $tab || 'dashboard' === $tab || ! is_user_logged_in() || ! is_account_page() || is_wc_endpoint_url() ) {
		return;
	}
	// Only the bare My Account page (the dashboard).
	global $wp;
	if ( ! empty( $wp->query_vars ) && array_intersect( array_keys( $wp->query_vars ), array_keys( WC()->query->get_query_vars() ) ) ) {
		return;
	}
	wp_safe_redirect( wc_get_account_endpoint_url( $tab ) );
	exit;
}

function perfectpixel_default_account_tab_menu( $items ) {
	if ( sanitize_key( '{{default_account_tab}}' ) && 'dashboard' !== sanitize_key( '{{default_account_tab}}' ) ) {
		unset( $items['dashboard'] );
	}
	return $items;
}
